-- Classic 1.60 (WoW Forever): Scourge Invasion spawns, from VMaNGOS db-4641790 (creature / gameobject / game_event_creature /
-- game_event_gameobject of events 17, 81, 90-99; GPL-2, VMaNGOS project). Converted to our schema with new guids
-- 29000001+ (creatures) and 35170001+ (objects). Nothing spawns until the event runs (Classic.ScourgeInvasion = 1 or .scourge on).
-- NPCs and objects that are not only for this event (Argent Dawn quest givers, the five dungeon bosses, banners) are added only
-- where our world has no spawn of the same entry within 5 yd on that map (outside this file's guids). Safe to run again.

DELETE FROM `game_event_creature` WHERE `guid` BETWEEN 29000001 AND 29005000;
DELETE FROM `game_event_gameobject` WHERE `guid` BETWEEN 35170001 AND 35175000;
DELETE FROM `creature` WHERE `guid` BETWEEN 29000001 AND 29005000;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 35170001 AND 35175000;



